import sys


def main():
    data = sys.stdin.read().split()
    n, T = int(data[0]), int(data[1])
    start = {}
    end = {}
    p = 2
    for _ in range(n):
        rid, t, ty = data[p], int(data[p + 1]), data[p + 2]
        p += 3
        if ty == 'in':
            start[rid] = t
        else:
            end[rid] = t
    best = -1
    for rid, t in start.items():
        if rid not in end or end[rid] > t + T:
            if best == -1 or t + T < best:
                best = t + T
    print(best)


